function calcularTurnosDisponibles() {

  function formatoFechaCompleta(fechaStr) {
    const dias = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
    const f = new Date(fechaStr + "T00:00:00");
    const dd = f.getDate().toString().padStart(2,'0');
    const mm = (f.getMonth()+1).toString().padStart(2,'0');
    return `${dias[f.getDay()]} ${dd}/${mm}/${f.getFullYear()}`;
  }
  const timeToMinutes = (h) => { const [a,b]=h.split(':').map(Number); return a*60+b; };
  const minutesToTime = (m) => `${Math.floor(m/60).toString().padStart(2,'0')}:${(m%60).toString().padStart(2,'0')}`;
  const solapa = (aIni,aFin,bIni,bFin) => aIni < bFin && aFin > bIni;

  // 1. Tiempo de servicio
  const tiempoData = $('When Executed by Another Workflow').first().json;
  let TIEMPO_SERVICIO = 30;
  if (tiempoData?.query) {
    if (typeof tiempoData.query === 'string' && tiempoData.query.includes(':')) {
      const [h,m] = tiempoData.query.split(':').map(Number);
      TIEMPO_SERVICIO = h*60+m;
    } else { TIEMPO_SERVICIO = parseInt(tiempoData.query) || 30; }
  }
  const TIEMPO_LAVADO = 45, TIEMPO_RECEPCION = 15, TIEMPO_PREPARACION = 15;

  // 2. Datos
  const feriados = new Set($('feriados').first().json.feriadosEncontrados || []);
  const tallerData = $('Get row(s) in sheet').first().json;

  // 3. Ocupados como INTERVALOS por día (no claves de 15 min)
  const ocupadosPorDia = {};
  $('Code').all().forEach(item => {
    const arr = Array.isArray(item.json) ? item.json : [item.json];
    arr.forEach(t => {
      if (t && t.dia && t.inicio && t.final) {
        (ocupadosPorDia[t.dia] ||= []).push({
          ini: timeToMinutes(t.inicio),
          fin: timeToMinutes(t.final)
        });
      }
    });
  });

  // 4. Horarios del taller
  const apertura = timeToMinutes(tallerData.Apertura);
  const cierre = timeToMinutes(tallerData.Cierre);
  const inicioAlmuerzo = timeToMinutes(tallerData['Inicio Almuerzo']);
  const finAlmuerzo = timeToMinutes(tallerData['Fin Almuerzo']);
  const inicioDesayuno = timeToMinutes(tallerData['Inicio Desayuno']);
  const finDesayuno = timeToMinutes(tallerData['Fin Desayuno']);

  // 5. Buscar
  const turnosDisponibles = [];
  let fecha = new Date();
  fecha.setHours(0,0,0,0);
  fecha.setDate(fecha.getDate() + 2); // buffer 48h (unificar con los 3 pilares)
  let diasBuscados = 0;

  while (turnosDisponibles.length < 4 && diasBuscados < 60) {
    const fechaStr = fecha.toISOString().split('T')[0];
    const dow = fecha.getDay();

    if (dow >= 1 && dow <= 5 && !feriados.has(fechaStr)) {
      const busy = ocupadosPorDia[fechaStr] || [];

      for (let hora = apertura; hora + TIEMPO_SERVICIO <= cierre; hora += 15) {
        const inicioMin = hora;
        const finServicio = hora + TIEMPO_SERVICIO;

        // el servicio no puede cruzar pausas
        if (solapa(inicioMin, finServicio, inicioAlmuerzo, finAlmuerzo)) continue;
        if (solapa(inicioMin, finServicio, inicioDesayuno, finDesayuno)) continue;

        const llegada = inicioMin - TIEMPO_RECEPCION;
        let entrega = finServicio + TIEMPO_LAVADO + TIEMPO_PREPARACION;
        if (entrega >= 780 && entrega < 855) entrega = 900; // 13:00–14:15 → 15:00 (solo informativo)

        // *** El choque se valida contra la ventana REAL del servicio (llegada→finServicio),
        //     NO contra "entrega", que es solo el dato de lavado/preparación que se le muestra
        //     al cliente y no ocupa el recurso del taller. ***
        const choca = busy.some(b => solapa(llegada, finServicio, b.ini, b.fin));
        if (choca) continue;

        turnosDisponibles.push({
          dia: fechaStr,
          inicio: minutesToTime(inicioMin),
          final: minutesToTime(finServicio),
          horarioLlegada: minutesToTime(llegada),
          horarioEntrega: minutesToTime(entrega),
          fechaFormato: formatoFechaCompleta(fechaStr),
          Id_Calendario: tallerData.Id_Calendario,
          tiempoAlmuerzo: 0
        });
        break; // un turno por día
      }
    }
    fecha.setDate(fecha.getDate() + 1);
    diasBuscados++;
  }

  turnosDisponibles.sort((a,b) =>
    a.dia === b.dia ? a.inicio.localeCompare(b.inicio) : new Date(a.dia) - new Date(b.dia)
  );

  return { turnosDisponibles: turnosDisponibles.slice(0,4), tiempoServicio: TIEMPO_SERVICIO, tiempoLavado: TIEMPO_LAVADO };
}

