function obtenerFeriados() {
  const feriadosData = $input.all();
  const feriados = [];

  // Fechas que NO queremos incluir aunque vengan como "Día festivo"
  const fechasExcluidas = ["2026-07-10"];

  feriadosData.forEach(item => {
    // Solo procesar si la descripción es "Día festivo"
    if (!item.json || item.json.description !== "Día festivo") return;
    if (item.json.start && item.json.start.date) {
      feriados.push(item.json.start.date);
    }
    if (item.json.end && item.json.end.date && item.json.start.date !== item.json.end.date) {
      const fechaInicio = new Date(item.json.start.date);
      const fechaFin = new Date(item.json.end.date);

      const fechaActual = new Date(fechaInicio);
      while (fechaActual < fechaFin) {
        feriados.push(fechaActual.toISOString().split('T')[0]);
        fechaActual.setDate(fechaActual.getDate() + 1);
      }
    }
  });

  const feriadosUnicos = [...new Set(feriados)]
    .filter(fecha => !fechasExcluidas.includes(fecha))
    .sort();

  return feriadosUnicos;
}

